<template>\n  <q-page padding>\n    <div class="q-pa-md">\n      <q-card class="glass-card">\n        <q-card-section>\n          <div class="text-h6">Subscriptions Dashboard</div>\n        </q-card-section>\n\n        <q-card-section>\n          <div class="row q-gutter-md">\n            <q-select v-model="store.filters.status" :options="statusOptions" label="Status" filled style="width: 200px" />\n            <q-select v-model="store.filters.plan" :options="planOptions" label="Plan" filled style="width: 200px" />\n            <q-input v-model="store.filters.search" label="Search" filled style="width: 300px" />\n          </div>\n        </q-card-section>\n\n        <q-separator />\n\n        <q-table\n          title="Subscriptions"\n          :rows="store.subscriptions"\n          :columns="columns"\n          row-key="_id"\n          :loading="store.isLoading"\n          :pagination="{ rowsPerPage: 10 }"\n          dense\n        >\n          <template v-slot:body-cell-actions="props">\n            <q-td :props="props">\n              <q-btn icon="visibility" flat dense @click="viewSubscription(props.row._id)" />\n            </q-td>\n          </template>\n        </q-table>\n      </q-card>\n\n      <q-card class="glass-card q-mt-md">\n        <q-card-section>\n          <div class="text-h6">Upcoming Renewals</div>\n        </q-card-section>\n\n        <q-list bordered separator>\n          <q-item v-for="sub in store.upcomingRenewals" :key="sub._id">\n            <q-item-section>\n              <q-item-label>{{ sub.customerId.firstName }} {{ sub.customerId.lastName }}</q-item-label>\n              <q-item-label caption>Plan: {{ sub.plan }} - Next Bill: {{ sub.nextBillDate }}</q-item-label>\n            </q-item-section>\n            <q-item-section side>\n              <q-badge :color="getAlertColor(sub.nextBillDate)">\n                {{ getDaysToBill(sub.nextBillDate) }} days\n              </q-badge>\n            </q-item-section>\n          </q-item>\n        </q-list>\n      </q-card>\n    </div>\n  </q-page>\n</template>\n\n<script setup>\nimport { onMounted, watch } from 'vue';\nimport { useSubscriptionStore } from '../stores/subscriptions';\nimport { date } from 'quasar';\n\nconst store = useSubscriptionStore();\n\nconst statusOptions = ['active', 'paused', 'cancelled'];\nconst planOptions = ['edge', 'apex'];\n\nconst columns = [\n  { name: 'customer', label: 'Customer', field: (row) => `${row.customerId.firstName} ${row.customerId.lastName}`, sortable: true },\n  { name: 'plan', label: 'Plan', field: 'plan', sortable: true },\n  { name: 'status', label: 'Status', field: 'status', sortable: true },\n  { name: 'nextBillDate', label: 'Next Bill', field: 'nextBillDate', sortable: true, format: (val) => date.formatDate(val, 'YYYY-MM-DD') },\n  { name: 'actions', label: 'Actions' },\n];\n\nconst viewSubscription = (id) => {\n  // TODO: Navigate to detail page or open dialog\n  console.log('View subscription', id);\n};\n\nconst getDaysToBill = (billDate) => {\n  const today = date.startOfDate(new Date(), 'day');\n  const bill = date.startOfDate(new Date(billDate), 'day');\n  return date.getDateDiff(bill, today, 'days');\n};\n\nconst getAlertColor = (billDate) => {\n  const days = getDaysToBill(billDate);\n  if (days <= 3) return 'red';\n  if (days <= 7) return 'orange';\n  return 'green';\n};\n\nonMounted(() => {\n  store.fetchSubscriptions();\n  store.fetchUpcomingRenewals();\n});\n\nwatch(() => store.filters, () => {\n  store.fetchSubscriptions();\n}, { deep: true });\n</script>